def _jsonl_status_counts(path: Path, field: str) -> dict[str, int]:
    counts: Counter[str] = Counter()
    try:
        with path.open(encoding="utf-8") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    row = json.loads(line)
                except json.JSONDecodeError:
                    continue
                value = row.get(field)
                if value not in (None, ""):
                    counts[str(value)] += 1
    except OSError:
        return {}
    return dict(sorted(counts.items()))


def _jsonl_field_values(path: Path, field: str) -> set[str]:
    values: set[str] = set()
    try:
        with path.open(encoding="utf-8") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    row = json.loads(line)
                except json.JSONDecodeError:
                    continue
                value = row.get(field)
                if value not in (None, ""):
                    values.add(str(value))
    except OSError:
        return set()
    return values


