def _market_gap_primitive_decision_counts(path: Path) -> dict[str, int]:
    counts: Counter[str] = Counter({"FOLLOW": 0, "AVOID": 0, "MIXED": 0})
    try:
        with path.open(encoding="utf-8") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    row = json.loads(line)
                except json.JSONDecodeError:
                    continue
                tokens = {
                    str(row[field]).strip().upper()
                    for field in MARKET_GAP_PRIMITIVE_TOKEN_FIELDS
                    if row.get(field) not in (None, "")
                }
                if tokens & MARKET_GAP_PRIMITIVE_AVOID_TOKENS:
                    counts["AVOID"] += 1
                elif tokens & MARKET_GAP_PRIMITIVE_FOLLOW_TOKENS:
                    counts["FOLLOW"] += 1
                else:
                    counts["MIXED"] += 1
    except OSError:
        return {"FOLLOW": 0, "AVOID": 0, "MIXED": 0}
    return dict(counts)


