def _nearmiss_market_entry_decision(row: dict) -> str:
    touch_class = str(row.get("market_touch_class") or row.get("offset_touch_class") or "").upper()
    decision_direction = str(row.get("decision_direction") or "").upper()
    branch_result = str(row.get("branch_result_binary") or "").upper()
    target_stop_result = str(row.get("target_stop_result") or "").upper()
    if (
        touch_class == "TARGET_FIRST_OR_ONLY"
        and decision_direction == "KEEP_CHALLENGER"
        and branch_result == "ACCEPTED"
    ):
        return "FOLLOW"
    if (
        touch_class == "STOP_FIRST_OR_ONLY"
        or decision_direction in {"KILL_OR_REDESIGN", "KEEP_REPAIR_OR_AVOID"}
        or branch_result == "REJECTED"
    ):
        return "AVOID"
    if target_stop_result == "STOP_FIRST_PROXY_DOMINANT" and decision_direction not in {
        "KEEP_CHALLENGER",
        "",
    }:
        return "AVOID"
    return "MIXED"


def _nearmiss_market_entry_counts(path: Path) -> dict:
    decision_counts: Counter[str] = Counter({"FOLLOW": 0, "AVOID": 0, "MIXED": 0})
    source_component_counts: Counter[str] = Counter()
    target_stop_counts: Counter[str] = Counter()
    decision_direction_counts: Counter[str] = Counter()
    route_candidate_ids: set[str] = set()
    rows: list[dict] = []
    try:
        with path.open(encoding="utf-8-sig") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    row = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(row, dict):
                    continue
                rows.append(row)
    except OSError:
        rows = []

    source_component = {
        "BRANCH_SUMMARY_LEDGER": "nofill_nearmiss_branch_summary",
        "MARKET_ENTRY_JOIN_LEDGER": "nofill_near_miss_market_entry",
        "OFFSET_JOIN_LEDGER": "nofill_near_miss_offset",
        "SOURCE_REQUIREMENT_JOIN_LEDGER": "nofill_near_miss_source_requirement",
    }
    component = ""
    for token, value in source_component.items():
        if token in path.name:
            component = value
            break

    for row in rows:
        decision_counts[_nearmiss_market_entry_decision(row)] += 1
        if component:
            source_component_counts[component] += 1
        if value := row.get("target_stop_result"):
            target_stop_counts[str(value)] += 1
        if value := row.get("decision_direction"):
            decision_direction_counts[str(value)] += 1
        if value := row.get("route_candidate_id"):
            route_candidate_ids.add(str(value))

    return {
        "row_count": len(rows),
        "runtime_decision_counts": dict(decision_counts),
        "runtime_source_component_counts": dict(sorted(source_component_counts.items())),
        "target_stop_result_counts": dict(sorted(target_stop_counts.items())),
        "decision_direction_counts": dict(sorted(decision_direction_counts.items())),
        "unique_route_candidate_count": len(route_candidate_ids),
        "symbol_counts": _jsonl_status_counts(path, "symbol"),
        "side_counts": _jsonl_status_counts(path, "side"),
        "route_candidate_ids_sample": sorted(route_candidate_ids)[:12],
    }


