def _is_nofill_pending_lifecycle_wave_path(path_text: str, source_path: Path) -> bool:
    lower = path_text.lower().replace("\\", "/")
    name = source_path.name.lower()
    if source_path.name in {
        NOFILL_PENDING_LIFECYCLE_RUNTIME_ROWS_NAME,
        NOFILL_PENDING_LIFECYCLE_RUNTIME_SUMMARY_NAME,
    }:
        return True
    if not any(token in lower or token in name for token in ("nofill", "no_fill", "pending", "prefill")):
        return False
    if any(
        token in lower
        for token in (
            "gtos_vnext_nofill_pending_lifecycle_runtime",
            "local_repaired_proxy",
            "system_transfer_nearmiss_market_entry_join",
            "system_transfer_market_gap_primitive_expansion",
            "expanded_market",
        )
    ):
        return False
    return True


@lru_cache(maxsize=1)
def _nofill_pending_lifecycle_runtime_summary() -> dict:
    path = REPO_ROOT / NOFILL_PENDING_LIFECYCLE_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _nofill_pending_lifecycle_source_stats_by_name() -> dict[str, dict]:
    summary = _nofill_pending_lifecycle_runtime_summary()
    stats = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        name = Path(str(item.get("path") or "")).name
        if name:
            stats[name] = item
    return stats


