def _opening_drive_source_contract_runtime_summary() -> dict:
    path = REPO_ROOT / OPENING_DRIVE_SOURCE_CONTRACT_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _opening_drive_source_contract_source_stats_by_name() -> dict[str, dict]:
    summary = _opening_drive_source_contract_runtime_summary()
    stats = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        name = Path(str(item.get("path") or "")).name
        if name:
            stats[name] = item
    return stats


def _is_opening_drive_source_contract_source(
    path_text: str,
    source_path: Path,
) -> bool:
    lower = path_text.lower().replace("\\", "/")
    if source_path.name in {
        OPENING_DRIVE_SOURCE_CONTRACT_RUNTIME_ROWS_NAME,
        OPENING_DRIVE_SOURCE_CONTRACT_RUNTIME_SUMMARY_NAME,
    }:
        return True
    return (
        "oti4_opening_drive_source_correction_or_contract_revision" in lower
        and source_path.name in OPENING_DRIVE_SOURCE_CONTRACT_SOURCE_NAMES
    )


