@lru_cache(maxsize=1)
def _numeric_router_catalog_runtime_summary() -> dict:
    path = REPO_ROOT / NUMERIC_ROUTER_CATALOG_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _numeric_router_catalog_stats_by_path() -> dict[str, dict]:
    summary = _numeric_router_catalog_runtime_summary()
    stats = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if raw_path:
            stats[raw_path.casefold().replace("\\", "/")] = item
    return stats


def _numeric_router_catalog_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _numeric_router_catalog_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
        source_path.name.casefold(),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


def _numeric_router_catalog_counts() -> tuple[dict, dict, dict, dict, dict, dict, dict, dict]:
    summary = _numeric_router_catalog_runtime_summary()

    def _dict(name: str) -> dict:
        value = summary.get(name)
        return value if isinstance(value, dict) else {}

    coverage = summary.get("coverage_counts")
    if not isinstance(coverage, dict):
        coverage = {}
    blank_anchors = summary.get("blank_anchor_counts")
    if not isinstance(blank_anchors, dict):
        blank_anchors = {}
    return (
        _dict("decision_counts"),
        _dict("source_component_counts"),
        _dict("source_role_counts"),
        _dict("source_group_counts"),
        _dict("r_evidence_class_counts"),
        _dict("system_surface_counts"),
        coverage,
        blank_anchors,
    )


def _numeric_router_catalog_source_state(source_path: Path) -> str:
    name = source_path.name.upper()
    if "AVOID" in name:
        return "CONVERTED_AVOID_FILTER"
    if "SCORER" in name:
        return "CONVERTED_FOLLOW_SCORER"
    return "CONVERTED_GATE_SELECTOR_FRAMEWORK_BEHAVIOR"


