def _legacy_ai_cascade_model_runtime_summary() -> dict:
    path = REPO_ROOT / LEGACY_AI_CASCADE_MODEL_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _legacy_ai_cascade_model_stats_by_path() -> dict[str, dict]:
    summary = _legacy_ai_cascade_model_runtime_summary()
    stats: dict[str, dict] = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if raw_path:
            stats[raw_path.casefold().replace("\\", "/")] = item
    return stats


