@lru_cache(maxsize=1)
def _execution_adjacent_friction_residue_runtime_summary() -> dict:
    path = REPO_ROOT / EXECUTION_ADJACENT_FRICTION_RESIDUE_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


@lru_cache(maxsize=1)
def _execution_adjacent_friction_residue_runtime_rows() -> tuple[dict, ...]:
    path = REPO_ROOT / EXECUTION_ADJACENT_FRICTION_RESIDUE_RUNTIME_ROWS_PATH
    rows: list[dict] = []
    try:
        with path.open(encoding="utf-8-sig") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    payload = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if isinstance(payload, dict):
                    rows.append(payload)
    except OSError:
        return ()
    return tuple(rows)


def _execution_adjacent_friction_residue_stats_by_path() -> dict[str, dict]:
    summary = _execution_adjacent_friction_residue_runtime_summary()
    stats: dict[str, dict] = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    runtime_rows = _execution_adjacent_friction_residue_runtime_rows()
    rows_by_path: Counter[str] = Counter()
    for row in runtime_rows:
        raw_path = str(
            row.get("source_artifact_path")
            or row.get("source_path")
            or row.get("source_artifact")
            or ""
        )
        if raw_path:
            rows_by_path[raw_path.casefold().replace("\\", "/")] += 1
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if not raw_path:
            continue
        normalized = raw_path.casefold().replace("\\", "/")
        payload = dict(item)
        payload["runtime_rows_read"] = int(
            payload.get("runtime_rows_read") or rows_by_path.get(normalized) or 0
        )
        stats[normalized] = payload
        stats.setdefault(Path(raw_path).name.casefold(), payload)
    return stats


def _execution_adjacent_friction_residue_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _execution_adjacent_friction_residue_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
        source_path.name.casefold(),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


