@lru_cache(maxsize=1)
def _exit_management_residue_runtime_summary() -> dict:
    path = REPO_ROOT / EXIT_MANAGEMENT_RESIDUE_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


@lru_cache(maxsize=1)
def _exit_management_residue_runtime_rows_by_source() -> dict[str, int]:
    path = REPO_ROOT / EXIT_MANAGEMENT_RESIDUE_RUNTIME_ROWS_PATH
    rows: list[dict] = []
    try:
        with path.open("r", encoding="utf-8-sig") as handle:
            for line in handle:
                line = line.strip()
                if line:
                    parsed = json.loads(line)
                    if isinstance(parsed, dict):
                        rows.append(parsed)
    except (OSError, json.JSONDecodeError):
        return {}
    counts: Counter[str] = Counter()
    for row in rows:
        source_artifact = str(row.get("source_artifact") or "")
        if not source_artifact:
            continue
        counts[source_artifact.casefold().replace("\\", "/")] += 1
        counts[Path(source_artifact).name.casefold()] += 1
    return dict(counts)


def _exit_management_residue_stats_by_path() -> dict[str, dict]:
    summary = _exit_management_residue_runtime_summary()
    stats: dict[str, dict] = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    runtime_rows_by_source = _exit_management_residue_runtime_rows_by_source()
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if not raw_path:
            continue
        runtime_rows_read = int(
            runtime_rows_by_source.get(raw_path.casefold().replace("\\", "/"))
            or runtime_rows_by_source.get(Path(raw_path).name.casefold())
            or 0
        )
        enriched = {**item, "runtime_rows_read": runtime_rows_read}
        stats[raw_path.casefold().replace("\\", "/")] = enriched
        stats[Path(raw_path).name.casefold()] = enriched
    return stats


def _exit_management_residue_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _exit_management_residue_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
        source_path.name.casefold(),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


