@lru_cache(maxsize=1)
def _main_orch24_snapshot_dependency_repair_runtime_summary() -> dict:
    path = REPO_ROOT / MAIN_ORCH24_SNAPSHOT_DEPENDENCY_REPAIR_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


@lru_cache(maxsize=1)
def _main_orch24_snapshot_dependency_repair_runtime_rows_by_source() -> dict[str, int]:
    path = REPO_ROOT / MAIN_ORCH24_SNAPSHOT_DEPENDENCY_REPAIR_RUNTIME_ROWS_PATH
    counts: Counter[str] = Counter()
    try:
        with path.open("r", encoding="utf-8-sig") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                row = json.loads(line)
                if not isinstance(row, dict):
                    continue
                source_artifact = str(row.get("source_artifact") or "")
                if not source_artifact:
                    continue
                counts[source_artifact.casefold().replace("\\", "/")] += 1
                counts[Path(source_artifact).name.casefold()] += 1
    except (OSError, json.JSONDecodeError):
        return {}
    return dict(counts)


def _main_orch24_snapshot_dependency_repair_stats_by_path() -> dict[str, dict]:
    summary = _main_orch24_snapshot_dependency_repair_runtime_summary()
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return {}
    runtime_rows_by_source = (
        _main_orch24_snapshot_dependency_repair_runtime_rows_by_source()
    )
    stats: dict[str, dict] = {}
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if not raw_path:
            continue
        runtime_rows_read = int(
            runtime_rows_by_source.get(raw_path.casefold().replace("\\", "/"))
            or runtime_rows_by_source.get(Path(raw_path).name.casefold())
            or item.get("runtime_rows_read")
            or 0
        )
        enriched = {**item, "runtime_rows_read": runtime_rows_read}
        stats[raw_path.casefold().replace("\\", "/")] = enriched
        stats[Path(raw_path).name.casefold()] = enriched
    return stats


def _main_orch24_snapshot_dependency_repair_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _main_orch24_snapshot_dependency_repair_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
        source_path.name.casefold(),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


