@lru_cache(maxsize=1)
def _instrument_expansion_market_session_runtime_summary() -> dict:
    path = REPO_ROOT / INSTRUMENT_EXPANSION_MARKET_SESSION_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


@lru_cache(maxsize=1)
def _instrument_expansion_market_session_runtime_rows_by_source() -> dict[str, int]:
    path = REPO_ROOT / INSTRUMENT_EXPANSION_MARKET_SESSION_RUNTIME_ROWS_PATH
    counts: Counter[str] = Counter()
    try:
        with path.open("r", encoding="utf-8-sig") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                row = json.loads(line)
                if not isinstance(row, dict):
                    continue
                source_artifact = str(row.get("source_artifact") or "")
                if not source_artifact:
                    continue
                normalized = source_artifact.casefold().replace("\\", "/")
                counts[normalized] += 1
                counts[Path(source_artifact).name.casefold()] += 1
    except (OSError, json.JSONDecodeError):
        return {}
    return dict(counts)


def _instrument_expansion_market_session_stats_by_path() -> dict[str, dict]:
    summary = _instrument_expansion_market_session_runtime_summary()
    runtime_rows_by_source = _instrument_expansion_market_session_runtime_rows_by_source()
    stats: dict[str, dict] = {}
    for item in summary.get("selected_source_units", []):
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if not raw_path:
            continue
        enriched = {
            "unit_id": item.get("unit_id"),
            "row_count": item.get("row_count"),
            "runtime_rows_read": runtime_rows_by_source.get(
                raw_path.casefold().replace("\\", "/"),
                runtime_rows_by_source.get(Path(raw_path).name.casefold(), 0),
            ),
            "support_line_count": item.get("support_line_count"),
        }
        stats[raw_path.casefold().replace("\\", "/")] = enriched
        stats[Path(raw_path).name.casefold()] = enriched
    for item in summary.get("source_artifacts", []):
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if not raw_path:
            continue
        enriched = {
            **item,
            "row_count": item.get("runtime_rows") or item.get("runtime_rows_read"),
            "runtime_rows_read": int(
                runtime_rows_by_source.get(raw_path.casefold().replace("\\", "/"))
                or item.get("runtime_rows")
                or item.get("runtime_rows_read")
                or 0
            ),
        }
        stats[raw_path.casefold().replace("\\", "/")] = enriched
    return stats


def _instrument_expansion_market_session_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _instrument_expansion_market_session_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


def _is_instrument_expansion_market_session_path(path_text: str, source_path: Path) -> bool:
    stats_by_path = _instrument_expansion_market_session_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
    )
    return any(key in stats_by_path for key in keys)


