def _is_gtos_vnext_bridge_residue_source_path(path_text: str) -> bool:
    summary = _gtos_vnext_bridge_residue_runtime_summary()
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return False
    normalized = path_text.casefold().replace("\\", "/")
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        source = str(item.get("path") or "").casefold().replace("\\", "/")
        if source and normalized == source:
            return True
    return False


