def _trade_record_execution_lifecycle_runtime_summary() -> dict:
    path = REPO_ROOT / TRADE_RECORD_EXECUTION_LIFECYCLE_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _trade_record_execution_lifecycle_stats_by_path() -> dict[str, dict]:
    summary = _trade_record_execution_lifecycle_runtime_summary()
    stats: dict[str, dict] = {}
    for collection_name in ("support_artifacts", "trade_record_artifacts"):
        artifacts = summary.get(collection_name)
        if not isinstance(artifacts, list):
            continue
        for item in artifacts:
            if not isinstance(item, dict):
                continue
            raw_path = str(item.get("path") or "")
            if not raw_path:
                continue
            normalized = {
                "path": raw_path,
                "rows": int(item.get("rows") or 1),
                "runtime_rows_read": int(item.get("runtime_rows_read") or 0),
                "sha256_or_git_blob": item.get("sha256_or_git_blob")
                or item.get("sha256")
                or "",
                "source_row_id": item.get("source_row_id", ""),
                "source_artifact_class": collection_name,
            }
            if collection_name == "trade_record_artifacts":
                normalized["rows"] = 1
                normalized["runtime_rows_read"] = 1
            path_key = raw_path.casefold().replace("\\", "/")
            stats[path_key] = normalized
            stats.setdefault(Path(raw_path).name.casefold(), normalized)
    return stats


def _trade_record_execution_lifecycle_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _trade_record_execution_lifecycle_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
        source_path.name.casefold(),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


def _trade_record_execution_lifecycle_counts() -> tuple[dict, dict, dict, dict, dict]:
    summary = _trade_record_execution_lifecycle_runtime_summary()

    def _dict(name: str) -> dict:
        value = summary.get(name)
        return value if isinstance(value, dict) else {}

    coverage = summary.get("coverage_counts")
    if not isinstance(coverage, dict):
        coverage = {}
    blank_anchors = summary.get("blank_anchor_counts")
    if not isinstance(blank_anchors, dict):
        blank_anchors = {}
    return (
        _dict("decision_counts"),
        _dict("source_component_counts"),
        _dict("source_role_counts"),
        coverage,
        blank_anchors,
    )


def _is_trade_record_execution_lifecycle_source(
    path_text: str,
    source_path: Path,
) -> bool:
    lower = path_text.casefold().replace("\\", "/")
    name = source_path.name.casefold()
    if name in {
        TRADE_RECORD_EXECUTION_LIFECYCLE_RUNTIME_ROWS_NAME.casefold(),
        TRADE_RECORD_EXECUTION_LIFECYCLE_RUNTIME_SUMMARY_NAME.casefold(),
    }:
        return True
    if lower in {
        "shadow_logs/trade_index_lifecycle_audit.jsonl",
        "shadow_logs/pending_limit_lifecycle_audit.jsonl",
    }:
        return False
    if "knowledge_base/trade_records/" in lower:
        return name != "_pending_records_index.json"
    return lower in {
        "knowledge_base/index/trade_record_inventory_index_2026-05-05.json",
        ".context/03_analysis/apr13_full_execution_audit.md",
        ".context/03_analysis/research_execution_plan_113q.md",
    }


