def _is_source_repair_missing_denominator_wave_path(path_text: str, source_path: Path) -> bool:
    lower = path_text.lower().replace("\\", "/")
    name = source_path.name.lower()
    if source_path.name in {
        SOURCE_REPAIR_MISSING_DENOMINATOR_RUNTIME_ROWS_NAME,
        SOURCE_REPAIR_MISSING_DENOMINATOR_RUNTIME_SUMMARY_NAME,
    }:
        return True
    if not any(token in lower or token in name for token in ("source_repair", "denominator", "missing", "fail_closed")):
        return False
    if any(
        token in lower
        for token in (
            "main_orch24_swing_protected",
            "gtos_vnext_source_repair_missing_denominator_runtime",
            "gtos_vnext_nofill_pending_lifecycle_runtime",
            "gtos_vnext_expanded_market_source_geometry_runtime",
            "local_repaired_proxy",
            "system_transfer_nearmiss_market_entry_join",
            "system_transfer_market_gap_primitive_expansion",
            "expanded_market",
            "nofill",
            "no_fill",
            "unified_system_candidate",
        )
    ):
        return False
    return True


@lru_cache(maxsize=1)
def _source_repair_missing_denominator_runtime_summary() -> dict:
    path = REPO_ROOT / SOURCE_REPAIR_MISSING_DENOMINATOR_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _source_repair_missing_denominator_source_stats_by_name() -> dict[str, dict]:
    summary = _source_repair_missing_denominator_runtime_summary()
    stats = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        name = Path(str(item.get("path") or "")).name
        if name:
            stats[name] = item
    return stats


