@lru_cache(maxsize=1)
def _branch_ambiguity_collapse_runtime_summary() -> dict:
    path = REPO_ROOT / BRANCH_AMBIGUITY_COLLAPSE_RUNTIME_SUMMARY_PATH
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(payload, dict):
        return {}
    if int(payload.get("runtime_row_count") or 0) <= 0:
        return {}
    return payload


def _branch_ambiguity_collapse_source_stats_by_path() -> dict[str, dict]:
    summary = _branch_ambiguity_collapse_runtime_summary()
    stats = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if raw_path:
            stats[raw_path.casefold().replace("\\", "/")] = item
            stats[Path(raw_path).name.casefold()] = item
    return stats


def _branch_ambiguity_collapse_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _branch_ambiguity_collapse_source_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
        source_path.name.casefold(),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


def _is_branch_ambiguity_collapse_source(path_text: str, source_path: Path) -> bool:
    lower = path_text.casefold().replace("\\", "/")
    name = source_path.name.casefold()
    if "ambiguity_collapse" not in lower and "ambiguity_collapse" not in name:
        return False
    return True


