@lru_cache(maxsize=1)
def _scid_noapi_source_repair_runtime_summary() -> dict:
    path = REPO_ROOT / SCID_NOAPI_SOURCE_REPAIR_RUNTIME_SUMMARY_PATH
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _scid_noapi_source_repair_source_match(path_text: str) -> bool:
    normalized = path_text.casefold().replace("\\", "/")
    return any(
        token in normalized for token in SCID_NOAPI_SOURCE_REPAIR_SOURCE_PATH_TOKENS
    )


def _scid_noapi_source_repair_stats_by_path() -> dict[str, dict]:
    summary = _scid_noapi_source_repair_runtime_summary()
    stats: dict[str, dict] = {}
    artifacts = summary.get("source_artifacts")
    if not isinstance(artifacts, list):
        return stats
    for item in artifacts:
        if not isinstance(item, dict):
            continue
        raw_path = str(item.get("path") or "")
        if raw_path:
            stats[raw_path.casefold().replace("\\", "/")] = item
            stats[Path(raw_path).name.casefold()] = item
    return stats


def _scid_noapi_source_repair_stats_for_path(
    path_text: str,
    source_path: Path,
) -> dict:
    stats_by_path = _scid_noapi_source_repair_stats_by_path()
    keys = (
        path_text.casefold().replace("\\", "/"),
        _normal_path(source_path).casefold().replace("\\", "/"),
        source_path.name.casefold(),
    )
    for key in keys:
        if key in stats_by_path:
            return stats_by_path[key]
    return {}


def _scid_noapi_source_repair_counts() -> tuple[dict, dict, dict, dict, dict, dict, dict, dict]:
    summary = _scid_noapi_source_repair_runtime_summary()

    def _dict(name: str) -> dict:
        value = summary.get(name)
        return value if isinstance(value, dict) else {}

    coverage = summary.get("coverage_counts")
    if not isinstance(coverage, dict):
        coverage = {}
    blank_anchors = summary.get("blank_anchor_counts")
    if not isinstance(blank_anchors, dict):
        blank_anchors = {}
    return (
        _dict("decision_counts"),
        _dict("source_component_counts"),
        _dict("source_role_counts"),
        _dict("source_group_counts"),
        _dict("action_class_counts"),
        _dict("r_evidence_class_counts"),
        coverage,
        blank_anchors,
    )


def _scid_noapi_source_repair_source_paths(path_text: str) -> tuple[str, ...]:
    summary = _scid_noapi_source_repair_runtime_summary()
    artifact_paths: list[str] = []
    artifacts = summary.get("source_artifacts")
    if isinstance(artifacts, list):
        for item in artifacts:
            if isinstance(item, dict) and item.get("path"):
                artifact_paths.append(str(item["path"]))
    return tuple(
        [
            path_text,
            SCID_NOAPI_SOURCE_REPAIR_RUNTIME_ROWS_PATH,
            SCID_NOAPI_SOURCE_REPAIR_RUNTIME_SUMMARY_PATH,
            "scripts/build_gtos_vnext_scid_noapi_source_repair_runtime_rows.py",
            "config/agent_config.yaml",
            "src/components/gtos_vnext_runtime.py",
            "tests/test_gtos_vnext_runtime.py",
            "tests/test_gtos_vnext_master_conversion_ledger.py",
            *artifact_paths,
        ]
    )


