def _is_ready8_failure_context_adjustment_source(path_text: str, source_path: Path) -> bool:
    lower = path_text.casefold().replace("\\", "/")
    name = source_path.name.casefold()
    if name in {READY8_CONTEXT_RISK_RULES_NAME.casefold(), READY8_CONTEXT_RISK_SUMMARY_NAME.casefold()}:
        return False
    if source_path.name in READY8_CONTEXT_RISK_SOURCE_NAMES:
        return False
    if name in {
        READY8_FAILURE_CONTEXT_ADJUSTMENT_RULES_NAME.casefold(),
        READY8_FAILURE_CONTEXT_ADJUSTMENT_SUMMARY_NAME.casefold(),
    }:
        return True
    if not (
        "2026-05-15" in lower
        or "2026_05_15" in lower
        or "2026-05-16" in lower
        or "2026_05_16" in lower
    ):
        return False
    return any(
        token in lower
        for token in (
            "ready8",
            "haz001",
            "haz-001",
            "haz005",
            "haz-005",
            "mac001",
            "mac-001",
            "mac004",
            "mac-004",
            "beh001",
            "beh-001",
            "unc004",
            "unc-004",
        )
    )


