def _accepted_builder_rejected_repair_decision_bucket(row: dict) -> str:
    action = str(
        row.get("next_layer_branch_action") or row.get("branch_system_recommendation") or ""
    ).upper()
    if action == "AVOID_SOURCE_BRANCH_UNTIL_EXACT_SOURCE_REPAIR_OR_COST_MODEL_CHANGE":
        return "AVOID_SOURCE_REPAIR"
    if action == "BUILD_M15_AVOID_OR_REDESIGN_FILTER":
        return "AVOID_M15_REDESIGN"
    if action == "REPAIR_SOURCE_OR_STRESS_POSITIVE_BRANCH_BEFORE_REPLAY":
        return "MIXED_POSITIVE_STRESS_CONTEXT"
    if "BINDING" in action:
        return "MIXED_BINDING_CONTEXT"
    return "MIXED_ENTRY_CONTEXT"


