def _control_screen_row_disposition(
    path_text: str,
    source_path: Path,
) -> ConversionDisposition | None:
    lower = path_text.lower().replace("\\", "/")
    if "weekend_mechanical_edge_factory_moonshot_2026_05_15" not in lower:
        return None
    if source_path.name != "HISTORICAL_OHLC_CONTROL_SCREEN_LEDGER_2026-05-15.jsonl":
        return None

    rows: list[dict] = []
    try:
        with source_path.open(encoding="utf-8-sig") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    rows.append(json.loads(line))
                except json.JSONDecodeError:
                    continue
    except OSError:
        rows = []

    line_count = len(rows)
    screen_bucket_counts = dict(sorted(Counter(str(row.get("screen_bucket")) for row in rows).items()))
    primitive_family_counts = dict(sorted(Counter(str(row.get("primitive_family")) for row in rows).items()))
    primitive_id_counts = dict(sorted(Counter(str(row.get("primitive_id")) for row in rows).items()))
    session_counts = dict(sorted(Counter(str(row.get("session")) for row in rows).items()))
    symbol_counts = dict(sorted(Counter(str(row.get("symbol")) for row in rows).items()))
    horizon_counts = dict(sorted(Counter(str(row.get("horizon_bars")) for row in rows).items()))
    expected_sign_counts = dict(sorted(Counter(str(row.get("expected_sign")) for row in rows).items()))
    material_sample_counts = dict(sorted(Counter(str(row.get("material_sample")) for row in rows).items()))
    material_directional_rows = sum(
        1
        for row in rows
        if row.get("material_sample") is True
        and row.get("expected_sign") in (1, -1)
    )
    follow_row_count = screen_bucket_counts.get("MATERIAL_POSITIVE_DIRECTIONAL_CONTROL_DELTA", 0)
    avoid_row_count = screen_bucket_counts.get("MATERIAL_NEGATIVE_DIRECTIONAL_CONTROL_DELTA", 0)
    neutral_guard_row_count = (
        screen_bucket_counts.get("MATERIAL_CONTRACTION_AFTER_NEUTRAL_PRIMITIVE", 0)
        + screen_bucket_counts.get("MATERIAL_EXPANSION_AFTER_NEUTRAL_PRIMITIVE", 0)
    )
    mixed_guard_row_count = screen_bucket_counts.get("MATERIAL_MIXED_DIRECTIONAL_CONTROL_DELTA", 0)
    small_guard_row_count = screen_bucket_counts.get("SMALL_OR_CONCENTRATED_SAMPLE", 0)
    source_paths = tuple(
        dict.fromkeys((
            path_text,
            "src/components/gtos_vnext_runtime.py",
            "config/agent_config.yaml",
            "tests/test_gtos_vnext_runtime.py",
            "tests/test_gtos_vnext_master_conversion_ledger.py",
            "research/science_program_2026_05/06_outcome_testing/weekend_mechanical_edge_factory_moonshot_2026_05_15/HISTORICAL_OHLC_CONTROL_SCREEN_RESULT_2026-05-15.json",
            "research/science_program_2026_05/06_outcome_testing/weekend_mechanical_edge_factory_moonshot_2026_05_15/HISTORICAL_OHLC_CONTROL_SCREEN_ROUTE_QUEUE_2026-05-15.jsonl",
        ))
    )
    return ConversionDisposition(
        evidence_family="moonshot_control_screen",
        runtime_surface="vnext_control_screen_context_guard",
        conversion_state="CONVERTED_GATE_SELECTOR_FRAMEWORK_BEHAVIOR",
        implemented_commit="pending_current_checkpoint_commit",
        tests_verifier=(
            "tests/test_gtos_vnext_runtime.py::"
            "test_moonshot_control_screen_rows_drive_primitive_context_behavior; "
            "tests/test_gtos_vnext_runtime.py::test_agent_config_wires_vnext_runtime_shadow_execution_path; "
            "tests/test_gtos_vnext_master_conversion_ledger.py::"
            "test_current_unit_converts_control_screen_rows_and_absorbs_result_summary; "
            "tests/test_gtos_vnext_master_conversion_ledger.py::"
            "test_moonshot_control_screen_ledger_is_runtime_converted"
        ),
        remaining_action=(
            "Converted the 2,565-row same-context control-screen ledger into "
            "runtime primitive/symbol/session/horizon context behavior. "
            f"{follow_row_count} positive directional rows cast FOLLOW scorer "
            f"pressure, {avoid_row_count} negative directional rows cast AVOID "
            f"filter pressure, {mixed_guard_row_count} mixed rows stay MIXED "
            f"context guards, {neutral_guard_row_count} neutral "
            "expansion/contraction rows stay MIXED context guards, and "
            f"{small_guard_row_count} small/concentrated rows stay MIXED "
            "guard evidence until controls mature."
        ),
        not_directly_convertible_reason="",
        next_code_config_test_action=(
            "Consume HISTORICAL_OHLC_CONTROL_SCREEN_ROUTE_QUEUE_2026-05-15.jsonl "
            "next; translate no-top-N route candidates into narrower routing, "
            "avoid, or exact repair behavior after this row-level control context "
            "is active in vNext matching."
        ),
        source_artifact_paths=source_paths,
        extra_fields={
            "row_count": line_count,
            "screen_bucket_counts": screen_bucket_counts,
            "primitive_family_counts": primitive_family_counts,
            "primitive_id_counts": primitive_id_counts,
            "session_counts": session_counts,
            "symbol_counts": symbol_counts,
            "horizon_counts": horizon_counts,
            "expected_sign_counts": expected_sign_counts,
            "material_sample_counts": material_sample_counts,
            "material_directional_rows": material_directional_rows,
            "runtime_match_fields_added_or_used": [
                "symbol",
                "source_symbol",
                "symbol_family",
                "route_session",
                "horizon_id",
                "primitive",
                "side",
                "route_family",
                "source_component",
                "action_class",
            ],
            "runtime_metric_fields": [
                "proxy_score",
                "effective_n",
            ],
            "runtime_decision_mapping": {
                "MATERIAL_POSITIVE_DIRECTIONAL_CONTROL_DELTA": "FOLLOW",
                "MATERIAL_NEGATIVE_DIRECTIONAL_CONTROL_DELTA": "AVOID",
                "MATERIAL_MIXED_DIRECTIONAL_CONTROL_DELTA": "MIXED",
                "MATERIAL_CONTRACTION_AFTER_NEUTRAL_PRIMITIVE": "MIXED",
                "MATERIAL_EXPANSION_AFTER_NEUTRAL_PRIMITIVE": "MIXED",
                "SMALL_OR_CONCENTRATED_SAMPLE": "MIXED",
            },
            "runtime_code_paths": [
                "src/components/gtos_vnext_runtime.py::_enrich_moonshot_control_screen_row",
                "src/components/gtos_vnext_runtime.py::evaluate_vnext_event",
                "src/components/gtos_vnext_runtime.py::apply_vnext_risk_adjustment",
                "src/components/gtos_vnext_runtime.py::vnext_execution_block_reason",
            ],
        },
    )


