def _git_ls_files_with_blob_hash(repo: Path, roots: Iterable[Path]) -> Iterable[tuple[Path, str]]:
    root_args = [str(root).replace("\\", "/") for root in roots]
    if not root_args:
        return
    cmd = ["git"]
    if repo.resolve() != REPO_ROOT.resolve():
        safe_repo = str(repo).replace("\\", "/")
        cmd.extend(["-c", f"safe.directory={safe_repo}"])
    cmd.extend(["-C", str(repo), "ls-files", "-s", "--", *root_args])
    output = subprocess.check_output(cmd, text=True, encoding="utf-8", errors="replace")
    for line in output.splitlines():
        # Format: "100644 <blob> 0\tpath"
        meta, rel = line.split("\t", 1)
        parts = meta.split()
        if len(parts) < 2:
            continue
        path = repo / rel
        if path.suffix.lower() not in INCLUDED_SUFFIXES:
            continue
        yield path, parts[1]


def _is_non_material_handoff_source_name(name: str) -> bool:
    return any(pattern.match(name) for pattern in NON_MATERIAL_HANDOFF_SOURCE_PATTERNS)


def iter_source_files() -> Iterable[tuple[Path, str, str]]:
    """Yield committed source artifacts with fast git-blob hashes.

    The repo carries ~10GB of tracked research/log artifacts. Hashing file
    contents at every checkpoint turns the control ledger into a slow wrapper
    task. Git blob hashes are exact committed-source hashes and keep the ledger
    tied to committed artifact identity without rereading multi-GB logs.
    """
    seen: set[str] = set()
    for path, blob_hash in _git_ls_files_with_blob_hash(REPO_ROOT, SCAN_ROOTS):
        if not path.exists():
            continue
        if _is_non_material_handoff_source_name(path.name):
            continue
        key = str(path.resolve()).casefold()
        if key in seen:
            continue
        seen.add(key)
        yield path, blob_hash, "git_blob"

    if MOONSHOT_ROUTE.exists() and MOONSHOT_REPO.exists():
        moonshot_root = MOONSHOT_ROUTE.relative_to(MOONSHOT_REPO)
        for path, blob_hash in _git_ls_files_with_blob_hash(MOONSHOT_REPO, (moonshot_root,)):
            if not path.exists():
                continue
            key = str(path.resolve()).casefold()
            if key in seen:
                continue
            seen.add(key)
            yield path, blob_hash, "git_blob"

    for rel_path in CURRENT_CHECKPOINT_GENERATED_ARTIFACT_PATHS:
        path = REPO_ROOT / rel_path
        if not path.exists():
            continue
        key = str(path.resolve()).casefold()
        if key in seen:
            continue
        seen.add(key)
        yield path, sha256_path(path), "sha256"


def iter_current_wave_long_path_source_files(
    existing_relpaths: set[str],
) -> Iterable[tuple[Path, str, str]]:
    """Yield focused long-path source children for the active runtime wave."""
    if not MOONSHOT_REPO.exists():
        return
    moonshot_root = MOONSHOT_ROUTE.relative_to(MOONSHOT_REPO)
    wanted = set(UNIFIED_SHADOW_SOURCE_MATERIALIZATION_LONG_PATH_SOURCE_NAMES)
    for path, blob_hash in _git_ls_files_with_blob_hash(MOONSHOT_REPO, (moonshot_root,)):
        if path.name not in wanted:
            continue
        # `git ls-files` reports index entries, which under a sparse checkout
        # include paths that are not materialized on disk. Both other consumers
        # of `_git_ls_files_with_blob_hash` filter those out (`iter_source_files`
        # above, twice); this one did not, so every non-materialized long-path
        # ledger entered the conversion ledger as a source artifact that does
        # not exist.
        if not path.exists():
            continue
        path_text = relpath(path)
        if path_text in existing_relpaths:
            continue
        existing_relpaths.add(path_text)
        yield path, blob_hash, "git_blob"


def _contains(text: str, *tokens: str) -> bool:
    return any(token in text for token in tokens)


