def build_rows() -> list[dict]:
    rows: list[dict] = []
    execution_position = 1
    self_outputs = {
        relpath(LEDGER_PATH),
        relpath(SUMMARY_PATH),
        relpath(BATCH_LEDGER_PATH),
        relpath(BATCH_SUMMARY_PATH),
    }
    source_files = sorted(
        (
            item for item in iter_source_files()
            if relpath(item[0]) not in self_outputs
        ),
        key=lambda item: relpath(item[0]).casefold(),
    )
    existing_relpaths = {relpath(path) for path, _, _ in source_files}
    source_files.extend(iter_current_wave_long_path_source_files(existing_relpaths))
    artifact_hash_by_path = {relpath(path): artifact_hash for path, artifact_hash, _ in source_files}

    for manual in MANUAL_UNITS:
        source_path = REPO_ROOT / manual["source_artifact_path"]
        rows.append({
            "schema_version": "gtos_vnext_master_intelligence_to_runtime_conversion_ledger_v1",
            "intelligence_unit_id": manual["intelligence_unit_id"],
            "execution_position": execution_position,
            "source_artifact_path": manual["source_artifact_path"],
            "source_artifact_hash": artifact_hash_by_path.get(
                manual["source_artifact_path"],
                sha256_path(source_path) if source_path.exists() else "",
            ),
            "source_artifact_hash_algorithm": (
                "git_blob" if manual["source_artifact_path"] in artifact_hash_by_path else "sha256"
            ),
            "source_artifact_paths": manual["source_artifact_paths"],
            "evidence_family": manual["evidence_family"],
            "affected_runtime_surface": manual["affected_runtime_surface"],
            "conversion_state": manual["conversion_state"],
            "implemented_commit": manual["implemented_commit"],
            "tests_verifier": manual["tests_verifier"],
            "remaining_action": manual["remaining_action"],
            "not_directly_convertible_reason": manual["not_directly_convertible_reason"],
            "missing_field_source": manual["missing_field_source"],
            "next_code_config_test_action": manual["next_code_config_test_action"],
        })
        execution_position += 1

    manual_source_paths = {unit["source_artifact_path"] for unit in MANUAL_UNITS}
    for path, artifact_hash, hash_algorithm in source_files:
        path_text = relpath(path)
        if path_text in manual_source_paths:
            continue
        disposition = classify_artifact(path_text, path)
        row = {
            "schema_version": "gtos_vnext_master_intelligence_to_runtime_conversion_ledger_v1",
            "intelligence_unit_id": f"UNIT_{execution_position:06d}",
            "execution_position": execution_position,
            "source_artifact_path": path_text,
            "source_artifact_hash": artifact_hash,
            "source_artifact_hash_algorithm": hash_algorithm,
            "source_artifact_paths": list(disposition.source_artifact_paths or (path_text,)),
            "evidence_family": disposition.evidence_family,
            "affected_runtime_surface": disposition.runtime_surface,
            "conversion_state": disposition.conversion_state,
            "implemented_commit": disposition.implemented_commit,
            "tests_verifier": disposition.tests_verifier,
            "remaining_action": disposition.remaining_action,
            "not_directly_convertible_reason": disposition.not_directly_convertible_reason,
            "missing_field_source": disposition.missing_field_source,
            "next_code_config_test_action": disposition.next_code_config_test_action,
        }
        if disposition.extra_fields:
            row.update(disposition.extra_fields)
        rows.append(row)
        execution_position += 1

    return rows


def validate_rows(rows: list[dict]) -> None:
    positions = [row["execution_position"] for row in rows]
    if positions != list(range(1, len(rows) + 1)):
        raise ValueError("execution positions are not contiguous")
    for row in rows:
        state = row["conversion_state"]
        if state not in ALLOWED_STATES:
            raise ValueError(f"illegal conversion state: {state}")
        if state == "NOT_STARTED" and not row.get("execution_position"):
            raise ValueError(f"NOT_STARTED row lacks execution position: {row['intelligence_unit_id']}")
        if state == "REPAIR_NEEDED_WITH_EXACT_FIELD_SOURCE_CODE_ACTION":
            for key in ("missing_field_source", "affected_runtime_surface", "next_code_config_test_action"):
                if not row.get(key):
                    raise ValueError(f"repair row lacks {key}: {row['intelligence_unit_id']}")
        if state == "KILLED_BY_COMPUTED_EVIDENCE_WITH_TESTED_REASON":
            if not row.get("tests_verifier") or not row.get("not_directly_convertible_reason"):
                raise ValueError(f"killed row lacks tested reason: {row['intelligence_unit_id']}")


def _previous_summary_counts() -> dict | None:
    summary_rel = relpath(SUMMARY_PATH)
    try:
        data_text = subprocess.check_output(
            ["git", "-C", str(REPO_ROOT), "show", f"HEAD:{summary_rel}"],
            text=True,
            encoding="utf-8",
            errors="replace",
        )
    except (OSError, subprocess.CalledProcessError):
        return None
    try:
        data = json.loads(data_text)
    except json.JSONDecodeError:
        return None
    return {
        "total_intelligence_units": data.get("total_intelligence_units"),
        "converted_units": data.get("converted_units"),
        "implemented_units": data.get("implemented_units"),
        "killed_units": data.get("killed_units"),
        "repair_action_defined_units": data.get(
            "repair_action_defined_units",
            data.get("repair_needed_units"),
        ),
        "not_started_units": data.get("not_started_units"),
    }


def _count_delta(current: dict, previous: dict | None) -> dict:
    keys = (
        "total_intelligence_units",
        "converted_units",
        "implemented_units",
        "killed_units",
        "repair_action_defined_units",
        "not_started_units",
    )
    if previous is None:
        return {
            "previous_summary_found": False,
            "baseline": "initial_master_ledger_materialization",
            "current_checkpoint_closed_or_advanced_units": list(CURRENT_UNIT_IDS),
            **{key: None for key in keys},
        }
    return {
        "previous_summary_found": True,
        **{
            key: (
                None if previous.get(key) is None
                else current.get(key, 0) - int(previous.get(key, 0))
            )
            for key in keys
        },
    }


def _next_priority_not_started_row(rows: list[dict]) -> dict | None:
    open_states = {
        "NOT_STARTED",
        "REPAIR_NEEDED_WITH_EXACT_FIELD_SOURCE_CODE_ACTION",
    }
    for row in rows:
        if row["conversion_state"] not in open_states:
            continue
        source_path = str(row.get("source_artifact_path") or "").casefold()
        if any(token in source_path for token in NEXT_PRIORITY_OPEN_ARTIFACT_TOKENS):
            return row

    not_started = [
        row for row in rows
        if row["conversion_state"] == "NOT_STARTED"
    ]
    if not not_started:
        return None

    current_tokens = (
        "cp280",
        "cp281",
        "cp282",
        "frozen_moonshot",
        "weekend_moonshot",
        "weekend_mechanical_edge_factory_moonshot",
        "moonshot",
    )
    primary_artifact_tokens = (
        "main_orch48_cp281",
        "cp280",
        "cp282",
    )
    def _is_current_priority(row: dict) -> bool:
        haystack = str(row.get("source_artifact_path") or "").casefold()
        return any(token in haystack for token in current_tokens)

    for row in not_started:
        source_path = str(row.get("source_artifact_path") or "").replace("\\", "/")
        if source_path.startswith(".context/02_session_handoffs/"):
            continue
        haystack = source_path.casefold()
        if (
            source_path.casefold().endswith((".jsonl", ".json"))
            and any(token in haystack for token in primary_artifact_tokens)
        ):
            return row
    for row in not_started:
        source_path = str(row.get("source_artifact_path") or "").replace("\\", "/")
        if source_path.startswith(".context/02_session_handoffs/"):
            continue
        haystack = source_path.casefold()
        if any(token in haystack for token in primary_artifact_tokens):
            return row
    for row in not_started:
        source_path = str(row.get("source_artifact_path") or "").replace("\\", "/")
        if source_path.startswith(".context/02_session_handoffs/"):
            continue
        if _is_current_priority(row):
            return row
    for row in not_started:
        if _is_current_priority(row):
            return row
    return not_started[0]


def _is_current_unit(row: dict) -> bool:
    if CURRENT_BATCH_WAVE_ID:
        return row.get("batch_wave_id") == CURRENT_BATCH_WAVE_ID
    source_path = str(row.get("source_artifact_path") or "").casefold().replace("\\", "/")
    if any(token in source_path for token in CURRENT_UNIT_SOURCE_TOKENS):
        return True
    return (
        not CURRENT_UNIT_SOURCE_TOKENS
        and row["intelligence_unit_id"] in set(CURRENT_UNIT_IDS)
    )


def build_summary(rows: list[dict]) -> dict:
    state_counts = Counter(row["conversion_state"] for row in rows)
    converted_states = {
        "CONVERTED_FOLLOW_SCORER",
        "CONVERTED_AVOID_FILTER",
        "CONVERTED_RISK_SIZING_RULE",
        "CONVERTED_AI_NARROWING_OR_AI_REMOVAL_RULE",
        "CONVERTED_MARKET_TIMEFRAME_ROUTER",
        "CONVERTED_NOFILL_PENDING_EXECUTION_BEHAVIOR",
        "CONVERTED_EXECUTION_ADJACENT_FRICTION_BEHAVIOR",
        "CONVERTED_EXECUTION_ADJACENT_TARGET_CONTROL_BEHAVIOR",
        "CONVERTED_SOURCE_REPAIR_MISSING_DENOMINATOR_GUARD",
        "CONVERTED_SIERRA_DEPTH_SOURCE_ACQUISITION_GATE",
        "CONVERTED_RISK_PROXY_STRESS_COST_RULE",
        "CONVERTED_GATE_SELECTOR_FRAMEWORK_BEHAVIOR",
    }
    current_rows = [row for row in rows if _is_current_unit(row)]
    current = current_rows[0] if current_rows else rows[0]
    next_row = _next_priority_not_started_row(rows)
    converted_units = sum(state_counts[state] for state in converted_states)
    repair_action_defined_units = state_counts["REPAIR_NEEDED_WITH_EXACT_FIELD_SOURCE_CODE_ACTION"]
    summary = {
        "schema_version": "gtos_vnext_master_intelligence_to_runtime_conversion_summary_v1",
        "ledger_path": relpath(LEDGER_PATH),
        "total_intelligence_units": len(rows),
        "implemented_units": state_counts["IMPLEMENTED_RUNTIME_CODE_CONFIG_TESTS"],
        "converted_units": converted_units,
        "converted_scorer_filter_risk_router_gate_execution_units": converted_units,
        "killed_units": state_counts["KILLED_BY_COMPUTED_EVIDENCE_WITH_TESTED_REASON"],
        "repair_action_defined_units": repair_action_defined_units,
        "repair_needed_units": repair_action_defined_units,
        "not_started_units": state_counts["NOT_STARTED"],
        "state_counts": dict(sorted(state_counts.items())),
        "current_unit_being_consumed": {
            "intelligence_unit_id": current["intelligence_unit_id"],
            "execution_position": current["execution_position"],
            "conversion_state": current["conversion_state"],
            "affected_runtime_surface": current["affected_runtime_surface"],
            "remaining_action": current["remaining_action"],
        },
        "current_units_consumed": [
            {
                "intelligence_unit_id": row["intelligence_unit_id"],
                "execution_position": row["execution_position"],
                "conversion_state": row["conversion_state"],
                "affected_runtime_surface": row["affected_runtime_surface"],
                "tests_verifier": row["tests_verifier"],
            }
            for row in current_rows
        ],
        "next_unit_being_consumed": None if next_row is None else {
            "intelligence_unit_id": next_row["intelligence_unit_id"],
            "execution_position": next_row["execution_position"],
            "conversion_state": next_row["conversion_state"],
            "source_artifact_path": next_row["source_artifact_path"],
            "evidence_family": next_row["evidence_family"],
            "affected_runtime_surface": next_row["affected_runtime_surface"],
            "remaining_action": next_row["remaining_action"],
        },
        "next_unit_hint": NEXT_UNIT_HINT,
    }
    summary["delta_since_previous_checkpoint"] = _count_delta(summary, _previous_summary_counts())
    return summary


OPEN_BATCH_STATES = {
    "NOT_STARTED",
    "REPAIR_NEEDED_WITH_EXACT_FIELD_SOURCE_CODE_ACTION",
}


def _batch_source_path(row: dict) -> Path:
    raw = str(row.get("source_artifact_path") or "")
    path = Path(raw)
    return path if path.is_absolute() else REPO_ROOT / path


def _lightweight_row_count(row: dict) -> int | None:
    value = row.get("row_count")
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    path = _batch_source_path(row)
    try:
        size = path.stat().st_size
    except OSError:
        return None
    if path.suffix.lower() in {".json"}:
        return 1
    if path.suffix.lower() not in {".jsonl", ".csv", ".txt", ".md"}:
        return None
    if size > 5_000_000:
        return None
    try:
        with path.open("rb") as handle:
            return sum(1 for line in handle if line.strip())
    except OSError:
        return None


