def _batch_freshness_tier(row: dict) -> str:
    path = str(row.get("source_artifact_path") or "").casefold()
    if "2026-05-18" in path or "main_orch48" in path:
        return "fresh_current_main_orch48_2026_05_18"
    if "2026-05-17" in path:
        return "fresh_moonshot_2026_05_17"
    if "2026-05-16" in path or "2026_05_15" in path:
        return "fresh_moonshot_2026_05_15_16"
    if "2026-05" in path:
        return "current_month_2026_05"
    return "legacy_or_durable_context"


def _batch_row_bearing_status(row: dict) -> str:
    path = str(row.get("source_artifact_path") or "").casefold()
    name = Path(path).name
    if any(token in name for token in ("question_ledger", "manifest", "summary", "verify", "readme")):
        return "wrapper_or_question_not_primary_row_bearing"
    if _lightweight_row_count(row) not in (None, 0):
        return "row_bearing"
    return "row_bearing_unknown_or_large"


